-- R-117/R-122. Only aggregate counts and declared usage; never private bodies.
CREATE FUNCTION dg_native_operations_metrics(p_workspace text,p_days integer,p_snapshot text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE v_actor text:=current_setting('digitalguide.actor_id',true);v_token text:=current_setting('digitalguide.auth_token_hash',true);v_tenant text;v_app text;v_from text;v_quota text;v_result jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM _dg_native_runtime_control c WHERE c.id=1 AND c.status='validation_only' AND c.environment='mock' AND c.app_role=session_user) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Operations aggregates require the current API runtime';END IF;
 IF p_days IS NULL OR p_days NOT IN(7,30,90) OR p_snapshot IS NULL OR p_snapshot !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Operations range is invalid';END IF;
 IF p_snapshot::timestamptz>statement_timestamp() OR p_snapshot::timestamptz<statement_timestamp()-interval '1 minute' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Operations snapshot is stale';END IF;
 SELECT m.tenant_id,c.app_env INTO v_tenant,v_app FROM memberships m JOIN workspaces w ON w.tenant_id=m.tenant_id AND w.id=p_workspace JOIN _dg_native_runtime_control c ON c.id=1 JOIN auth_sessions a ON a.user_id=m.user_id AND a.token_hash=v_token AND a.environment=c.environment AND a.app_env=c.app_env AND a.expires_at::timestamptz>statement_timestamp() WHERE m.user_id=v_actor AND m.role='admin' AND m.workspace_ids::jsonb ? p_workspace;
 IF v_tenant IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Operations require an active admin session and current workspace';END IF;
 v_from:=to_char(((date_trunc('day',p_snapshot::timestamptz AT TIME ZONE 'Asia/Shanghai')-(p_days-1)*interval '1 day') AT TIME ZONE 'Asia/Shanghai') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
 v_quota:=substring(p_snapshot FROM 1 FOR 10)||'T00:00:00.000Z';
 SELECT coalesce(jsonb_agg(to_jsonb(payload)),'[]'::jsonb) INTO v_result FROM(
WITH scope(tenant,workspace,environment,app_env,start_at,snapshot_at,quota_start) AS(SELECT v_tenant,p_workspace,'mock',v_app,v_from,p_snapshot,v_quota) SELECT 'activity' AS "kind",'video_projects' AS "source",CASE WHEN t.archived=1 THEN 'archived' ELSE 'draft' END AS "bucket",to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD') AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM studio_projects t  CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace AND t.environment=s.environment AND t.app_env=s.app_env AND t.created_at>=s.start_at AND t.created_at<=s.snapshot_at AND t.purpose='video' GROUP BY CASE WHEN t.archived=1 THEN 'archived' ELSE 'draft' END,to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD')
UNION ALL
SELECT 'activity' AS "kind",'video_exports' AS "source",t.status AS "bucket",to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD') AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM studio_exports t JOIN studio_projects p ON p.id=t.project_id AND p.tenant_id=t.tenant_id AND p.workspace_id=t.workspace_id CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace AND t.environment=s.environment AND t.app_env=s.app_env AND t.created_at>=s.start_at AND t.created_at<=s.snapshot_at AND p.purpose='video' GROUP BY t.status,to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD')
UNION ALL
SELECT 'activity' AS "kind",'presentation_projects' AS "source",CASE WHEN t.archived=1 THEN 'archived' ELSE 'draft' END AS "bucket",to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD') AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM studio_projects t  CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace AND t.environment=s.environment AND t.app_env=s.app_env AND t.created_at>=s.start_at AND t.created_at<=s.snapshot_at AND t.purpose='presentation' GROUP BY CASE WHEN t.archived=1 THEN 'archived' ELSE 'draft' END,to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD')
UNION ALL
SELECT 'activity' AS "kind",'presentation_sessions' AS "source",t.state AS "bucket",to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD') AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM studio_presentation_sessions t  CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace AND t.environment=s.environment AND t.app_env=s.app_env AND t.created_at>=s.start_at AND t.created_at<=s.snapshot_at GROUP BY t.state,to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD')
UNION ALL
SELECT 'activity' AS "kind",'live_sessions' AS "source",t.status AS "bucket",to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD') AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM live_sessions t  CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace AND t.environment=s.environment AND t.app_env=s.app_env AND t.created_at>=s.start_at AND t.created_at<=s.snapshot_at GROUP BY t.status,to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD')
UNION ALL
SELECT 'activity' AS "kind",'reception_sessions' AS "source",t.status AS "bucket",to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD') AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM reception_sessions t  CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace AND t.environment=s.environment AND t.app_env=s.app_env AND t.created_at>=s.start_at AND t.created_at<=s.snapshot_at AND t.service_scene='reception' GROUP BY t.status,to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD')
UNION ALL
SELECT 'activity' AS "kind",'restaurant_sessions' AS "source",t.status AS "bucket",to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD') AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM reception_sessions t  CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace AND t.environment=s.environment AND t.app_env=s.app_env AND t.created_at>=s.start_at AND t.created_at<=s.snapshot_at AND t.service_scene='restaurant' GROUP BY t.status,to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD')
UNION ALL
SELECT 'activity' AS "kind",'restaurant_orders' AS "source",t.status AS "bucket",to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD') AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM restaurant_orders t JOIN restaurants r ON r.id=t.restaurant_id CROSS JOIN scope s WHERE r.tenant_id=s.tenant AND r.workspace_id=s.workspace AND r.environment=s.environment AND r.app_env=s.app_env AND t.created_at>=s.start_at AND t.created_at<=s.snapshot_at GROUP BY t.status,to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD')
UNION ALL
SELECT 'activity' AS "kind",'character_jobs' AS "source",t.status AS "bucket",to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD') AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM character_jobs t  CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace AND t.environment=s.environment AND t.app_env=s.app_env AND t.created_at>=s.start_at AND t.created_at<=s.snapshot_at GROUP BY t.status,to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD')
UNION ALL
SELECT 'activity' AS "kind",'provider_jobs' AS "source",t.status AS "bucket",to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD') AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM jobs t  CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace AND t.environment=s.environment AND t.created_at>=s.start_at AND t.created_at<=s.snapshot_at GROUP BY t.status,to_char(t.created_at::timestamptz AT TIME ZONE 'Asia/Shanghai','YYYY-MM-DD')
UNION ALL
SELECT 'inventory' AS "kind",'assets' AS "source",'' AS "bucket",'' AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM assets t CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace
UNION ALL
SELECT 'inventory' AS "kind",'archivedAssets' AS "source",'' AS "bucket",'' AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM assets t CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace AND t.archived=1
UNION ALL
SELECT 'inventory' AS "kind",'expiredUnarchivedAssets' AS "source",'' AS "bucket",'' AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM assets t CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace AND t.archived=0 AND t.expires_at IS NOT NULL AND t.expires_at<=s.snapshot_at
UNION ALL
SELECT 'inventory' AS "kind",'registeredOriginals' AS "source",'' AS "bucket",'' AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM uploads t CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace AND EXISTS(SELECT 1 FROM assets a WHERE a.upload_id=t.id AND a.tenant_id=t.tenant_id AND a.workspace_id=t.workspace_id)
UNION ALL
SELECT 'inventory' AS "kind",'registeredOriginalBytes' AS "source",'' AS "bucket",'' AS "day",'' AS "currency",CAST(coalesce(sum(t.size),0) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM uploads t CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace AND EXISTS(SELECT 1 FROM assets a WHERE a.upload_id=t.id AND a.tenant_id=t.tenant_id AND a.workspace_id=t.workspace_id)
UNION ALL
SELECT 'inventory' AS "kind",'profiles' AS "source",'' AS "bucket",'' AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM profiles t CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace
UNION ALL
SELECT 'inventory' AS "kind",'membersWithAccess' AS "source",'' AS "bucket",'' AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM memberships t CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.role IN('admin','editor','viewer','reviewer') AND t.workspace_ids::jsonb ? s.workspace
UNION ALL
SELECT 'inventory' AS "kind",'workspaceCoreTasksToday' AS "source",'' AS "bucket",'' AS "day",'' AS "currency",CAST(count(*) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM jobs t CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace AND t.environment=s.environment AND t.created_at>=s.quota_start AND t.created_at<=s.snapshot_at
UNION ALL
SELECT 'inventory' AS "kind",'dailyCoreTaskLimit' AS "source",'' AS "bucket",'' AS "day",'' AS "currency",CAST(max(t.daily_limit) AS TEXT) AS "n",CAST('0' AS TEXT) AS "units",CAST('0' AS TEXT) AS "known_records",CAST('0' AS TEXT) AS "missing_records",CAST('0' AS TEXT) AS "known_minor" FROM tenants t CROSS JOIN scope s WHERE t.id=s.tenant
UNION ALL
SELECT 'usage' AS "kind",'provider_usage' AS "source",j.kind AS "bucket",'' AS "day",t.currency AS "currency",CAST(count(*) AS TEXT) AS "n",CAST(coalesce(sum(t.units),0) AS TEXT) AS "units",CAST(sum(CASE WHEN t.cost_minor IS NOT NULL THEN 1 ELSE 0 END) AS TEXT) AS "known_records",CAST(sum(CASE WHEN t.cost_minor IS NULL THEN 1 ELSE 0 END) AS TEXT) AS "missing_records",CAST(coalesce(sum(t.cost_minor),0) AS TEXT) AS "known_minor" FROM provider_usage t JOIN jobs j ON j.id=t.job_id AND j.tenant_id=t.tenant_id AND j.workspace_id=t.workspace_id AND j.environment=t.environment CROSS JOIN scope s WHERE t.tenant_id=s.tenant AND t.workspace_id=s.workspace AND t.environment=s.environment AND t.created_at>=s.start_at AND t.created_at<=s.snapshot_at GROUP BY j.kind,t.currency ORDER BY "kind","source","bucket","day","currency"
 ) payload;RETURN v_result;
END;$dg$;
REVOKE ALL ON FUNCTION dg_native_operations_metrics(text,integer,text) FROM PUBLIC;
